import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * `closeTrigger` is a sixth part. It is here for reference-app parity (CDC §4.5): `tabs` replaces `EditorTabs`, a
 * bar of closable documents. The branch it opens is not outside the pattern —
 * APG Tabs already spells `Delete` as the keyboard route to closing a tab, so
 * the button is the pointer route to something the pattern owns.
 */
export type TabsPart =
  | "root"
  | "list"
  | "trigger"
  | "indicator"
  | "content"
  | "closeTrigger"
  | "scrollbar"
  | "thumb";

export const anatomy: Anatomy<TabsPart> = createAnatomy("tabs").parts(
  "root",
  "list",
  "trigger",
  "indicator",
  "content",
  "closeTrigger",
  "scrollbar",
  "thumb",
);

export const parts: Record<TabsPart, AnatomyPart> = anatomy.build();

export interface TabsCssVars {
  // --- written ---
  /** Index of the selected tab. */
  "--sui-active-index": "<integer>";
  /** Number of tabs. */
  "--sui-item-count": "<integer>";
  /** Measured offset of the indicator, absent until it has been measured. */
  "--sui-indicator-offset": "<length>";
  /** Measured size of the indicator, absent until it has been measured. */
  "--sui-indicator-size": "<length>";
  /** Length of the inline scrollbar thumb. */
  "--sui-scroll-thumb-length": "<length>";
  /** Offset of the inline scrollbar thumb along its track. */
  "--sui-scroll-thumb-offset": "<length>";
}

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./tabs.anatomy";
import {
  getCloseTriggerId,
  getContentId,
  getIndicatorId,
  getListEl,
  getListId,
  getRootId,
  getScrollbarId,
  getThumbId,
  getTriggerId,
} from "./tabs.dom";
import type {
  TabsApi,
  TabsCloseTriggerProps,
  TabsContentProps,
  TabsSchema,
  TabsTriggerProps,
} from "./tabs.types";

export function connect<T extends PropTypes>(
  service: Service<TabsSchema>,
  normalize: NormalizeProps<T>,
): TabsApi<T> {
  const { context, computed, prop, refs, send, scope } = service;

  const selected = computed("selected");
  const disabled = !computed("interactive");
  const orientation = prop("orientation");
  const closable = prop("closable");
  const lazyMount = prop("lazyMount");
  const keepMounted = prop("keepMounted");

  const focusedValue = context.get("focusedValue");
  // Read once, when the focus landed, and held: the modality of *now* flips to
  // pointer after 300 ms of mouse movement whether or not the focus moved, and a
  // ring that blinks out under the user's hands was the result.
  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  const tabbableValue = context.get("tabbableValue");
  const offset = context.get("indicatorOffset");
  const size = context.get("indicatorSize");

  const isSelected = (value: string): boolean => value === selected;

  /** The `lazyMount` gate: whether the panel should be rendered at all. */
  const isMounted = (value: string): boolean =>
    !lazyMount || value === selected || refs.get("visited").has(value);

  /**
   * Whether the panel is expected in the document *right now*, which is what
   * `aria-controls` may name. Without `keepMounted` an inactive panel is unmounted
   * by the adapter's presence path, and an IDREF pointing at what it left behind is
   * exactly the `aria-valid-attr-value` violation. Missing is allowed here —
   * `aria-controls` is recommended on `role="tab"`, not required — dangling is not.
   */
  const hasPanel = (value: string): boolean =>
    isMounted(value) && (value === selected || keepMounted);

  return {
    value: selected,
    focusedValue,
    disabled,
    isSelected,
    isMounted,

    setValue(value: string | null): void {
      send({ type: "VALUE.SET", value });
    },

    selectNext(): void {
      send({ type: "LIST.NEXT" });
    },

    selectPrev(): void {
      send({ type: "LIST.PREV" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        "data-orientation": orientation,
        "data-disabled": dataAttr(disabled),
      }),

    getListProps: (): T["element"] =>
      normalize.element({
        ...parts.list.attrs,
        id: getListId(scope),
        role: "tablist",
        // Always emitted: `aria-orientation` is valid on `tablist` in both axes,
        // and a horizontal tab list that says so is one an AT can describe.
        "aria-orientation": orientation,
        "aria-describedby": prop("describedBy"),
        "data-orientation": orientation,
        "data-disabled": dataAttr(disabled),
        // Coming back to the bar lands on the tab that was left (default entry
        // strategy `last`, geometric fallback).
        "data-snav": "container",
        style: {
          // Kept for the equal-column presentations and for reading parity with
          // `toggle-group` — but they do not place this indicator. Tabs are as wide
          // as their labels, so an index is no longer a position.
          "--sui-active-index": String(context.get("activeIndex")),
          "--sui-item-count": String(context.get("itemCount")),
          "--sui-indicator-offset": offset === null ? undefined : `${offset}px`,
          "--sui-indicator-size": size === null ? undefined : `${size}px`,
        },
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        "aria-hidden": ariaAttr(true),
        "data-orientation": orientation,
        "data-empty": dataAttr(offset === null),
        // The pill must not play a spring because the window moved, a font
        // finished loading, or the page has only just been painted.
        "data-immediate": dataAttr(!context.get("indicatorAnimated")),
      }),

    getScrollbarProps: (): T["element"] =>
      normalize.element({
        ...parts.scrollbar.attrs,
        id: getScrollbarId(scope),
        "aria-hidden": ariaAttr(true),
        "data-orientation": "horizontal",
      }),

    getThumbProps: (): T["element"] =>
      normalize.element({ ...parts.thumb.attrs, id: getThumbId(scope) }),

    getTriggerProps: (triggerProps: TabsTriggerProps): T["button"] => {
      const { value } = triggerProps;
      const active = isSelected(value);
      const itemDisabled = disabled || triggerProps.disabled === true;
      const focused = focusedValue === value;

      return normalize.button({
        ...parts.trigger.attrs,
        id: getTriggerId(scope, value),
        type: "button",
        role: "tab",
        disabled: itemDisabled,
        "aria-selected": boolAttr(active),
        "aria-controls": hasPanel(value) ? getContentId(scope, value) : undefined,
        // Roving: the tab list holds exactly one stop in the tab order. It rides on
        // the selection when there is one — but it cannot be *derived* from it. A
        // controlled consumer may hold `value` at `null`, which the types call a
        // value rather than an absence, and `syncTriggers` is right not to settle it
        // on their behalf; deriving the stop from the selection then left every
        // trigger at `-1` and took the whole list out of the tab order.
        // `tabbableValue` is that tab, and it is never a disabled one.
        //
        // And when there is neither — no selection and no sync, which is what a
        // server render of an unselected list is — nothing is written at all. `-1`
        // on every trigger was that same disappearance one render earlier. The
        // triggers are buttons, so saying nothing leaves them in the browser's
        // order until the first sync, which is where "exactly one selected tab"
        // gets settled for a consumer who named none.
        tabIndex:
          tabbableValue === null && selected === null
            ? undefined
            : active || value === tabbableValue
              ? 0
              : -1,
        // The value lives on the element because the DOM is where the tab order is
        // read from — this is what keeps the machine out of a registry.
        "data-value": value,
        "data-label": triggerProps.label,
        "data-state": active ? "active" : "inactive",
        "data-disabled": dataAttr(itemDisabled),
        "data-orientation": orientation,
        "data-closable": dataAttr(closable),
        "data-focus-visible": dataAttr(focused && focusVisible),
        // On the focused tab only: the composite has one focus, and an attribute
        // claiming otherwise on every tab describes nothing.
        "data-focus-source": focused ? (focusSource ?? undefined) : undefined,
        onClick(event) {
          if (event.defaultPrevented || itemDisabled) return;
          send({ type: "TRIGGER.CLICK", value });
        },
        // Middle click closes, the universal convention of editor tab bars. It is
        // `auxclick` and not `mousedown` because Chromium starts autoscroll on the
        // latter.
        onAuxClick(event) {
          if (event.defaultPrevented || event.button !== 1 || !closable || itemDisabled) return;
          event.preventDefault();
          send({ type: "TRIGGER.CLOSE", value });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          // Shift+arrow is the range-selection gesture and belongs to the components
          // that have ranges; consuming it here would move the focus mid-selection.
          if (event.shiftKey) return;

          if (event.key === "Delete") {
            // Auto-repeat is a key being held, not a second press. Without the
            // filter a leaned-on Delete asks the consumer to close tabs it has
            // already been asked to remove.
            if (!closable || itemDisabled || event.repeat) return;
            event.preventDefault();
            send({ type: "TRIGGER.CLOSE", value });
            return;
          }

          // Enter activates on keydown and Space on keyup — the APG split that
          // `research/input.md` §1 makes a rule across the library, and that
          // `button` already keeps. Not prevented: on a real `<button>` the browser
          // turns both into a click and the second commit is a no-op. This path is
          // what keeps a substituted element correct.
          if (event.key === "Enter") {
            if (itemDisabled || event.repeat) return;
            send({ type: "TRIGGER.ACTIVATE", value });
            return;
          }
          // Space is claimed here so the arrow lookup below cannot see it, and
          // answered on keyup.
          if (event.key === " ") return;

          // `bothAxes: false`: off-axis the arrow stays the browser's and scrolls
          // the page, so the key is only prevented when it was actually claimed.
          const action = getRovingKeyAction(event.key, {
            orientation,
            dir: resolveDir(prop("dir"), getListEl(scope)),
            bothAxes: false,
          });
          if (action === null) return;
          event.preventDefault();
          send({ type: "TRIGGER.NAVIGATE", action, value });
        },
        // The other half of the Enter/Space split. A person who pressed Space, then
        // moved off the tab before letting go, has cancelled — which is what the
        // browser's own button does, and what falls out of listening on keyup.
        onKeyUp(event) {
          if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
          if (event.shiftKey || event.key !== " " || itemDisabled) return;
          send({ type: "TRIGGER.ACTIVATE", value });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.FOCUS", value });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.BLUR" });
        },
      });
    },

    getContentProps: (contentProps: TabsContentProps): T["element"] => {
      const { value } = contentProps;
      const active = isSelected(value);

      return normalize.element({
        ...parts.content.attrs,
        id: getContentId(scope, value),
        role: "tabpanel",
        "aria-labelledby": getTriggerId(scope, value),
        // Measured, not assumed: a panel with nothing tabbable in it needs a stop
        // of its own, and one that has a link or a field must not add an empty one
        // in front of it.
        tabIndex: active && context.get("contentTabbable") ? 0 : undefined,
        // Only in `keepMounted` mode. Without it the panel is unmounted by the
        // adapter's presence path, and `hidden` would kill its exit animation.
        hidden: !active && keepMounted ? true : undefined,
        "data-state": active ? "active" : "inactive",
        "data-orientation": orientation,
      });
    },

    getCloseTriggerProps: (closeProps: TabsCloseTriggerProps): T["button"] => {
      const { value } = closeProps;
      const itemDisabled = disabled || closeProps.disabled === true;

      return normalize.button({
        ...parts.closeTrigger.attrs,
        id: getCloseTriggerId(scope, value),
        type: "button",
        // A redundant pointer affordance, and it says so. `role="tablist"` may only
        // own `role="tab"`, so a close button standing in the bar is
        // `aria-required-children` however it is dressed — measured, not reasoned:
        // `role="none"` adds three violations of its own, a `presentation` wrapper
        // changes nothing because axe walks through it, and nesting the button
        // inside the tab trades the rule for `nested-interactive`. Hiding it is the
        // one clean composition, and it costs an assistive technology nothing: APG's
        // own keyboard route to closing is `Delete` on the tab, which the machine
        // implements. `tabindex="-1"` is focusable and not tabbable, the one shape
        // `aria-hidden-focus` accepts outright — so this is zero violations *and*
        // zero incompletes, not a rule traded for another.
        "aria-hidden": ariaAttr(true),
        // The tab list exposes exactly one stop in the tab order, and it is the
        // selected tab. The keyboard route to closing is `Delete`, per APG.
        tabIndex: -1,
        disabled: itemDisabled,
        "data-value": value,
        "data-disabled": dataAttr(itemDisabled),
        onClick(event) {
          if (event.defaultPrevented || itemDisabled) return;
          send({ type: "TRIGGER.CLOSE", value });
        },
      });
    },
  };
}

import { contains, queryAll } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "tabs";

/**
 * Written out rather than read from `parts`: the anatomy builds the same two
 * strings, and a component that imports its own anatomy into its DOM helpers pays
 * for the builder in every bundle that only wanted a query.
 */
const ROOT_SELECTOR = '[data-part~="tabs:root"]';
const TRIGGER_SELECTOR = '[data-part~="tabs:trigger"]';

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getListId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "list");
}

export function getScrollbarId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "scrollbar");
}

export function getThumbId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "thumb");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getTriggerId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "trigger", value);
}

export function getContentId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "content", value);
}

export function getCloseTriggerId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "close-trigger", value);
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getListEl(scope: Scope): HTMLElement | null {
  return scope.getById(getListId(scope));
}

export function getScrollbarEl(scope: Scope): HTMLElement | null {
  return scope.getById(getScrollbarId(scope));
}

export function getThumbEl(scope: Scope): HTMLElement | null {
  return scope.getById(getThumbId(scope));
}

export function getTriggerEl(scope: Scope, value: string): HTMLElement | null {
  return scope.getById(getTriggerId(scope, value));
}

export function getContentEl(scope: Scope, value: string): HTMLElement | null {
  return scope.getById(getContentId(scope, value));
}

/**
 * The trigger order is the DOM order, read when it is needed rather than kept in
 * a registry the consumer would have to maintain — the same decision as
 * `toggle-group`, for the same reason: a composite that has to be told about its
 * own children goes out of sync the first time one is rendered conditionally.
 *
 * The filter is what `toggle-group` never needed. A `tabs` inside a panel of
 * another `tabs` is an ordinary shape, and `querySelectorAll` from the outer root
 * would hand the outer machine the inner tabs' triggers — an `activeIndex` and an
 * indicator measured against a list nobody is looking at.
 */
export function getTriggerEls(scope: Scope): HTMLElement[] {
  const root = getRootEl(scope);
  if (root === null) return [];
  return queryAll<HTMLElement>(root, TRIGGER_SELECTOR).filter(
    (trigger) => trigger.closest(ROOT_SELECTOR) === root,
  );
}

export function getTriggerValues(scope: Scope): string[] {
  return getTriggerEls(scope).map((trigger) => trigger.dataset.value ?? "");
}

/**
 * Whether the focus is inside *this* tabs and not inside a `tabs` nested in it.
 *
 * The nearest `tabs:root` ancestor decides, and deliberately not the order of the
 * intent scope stack: React runs a child's effects before its parent's, so a
 * nested `tabs` pushes its scope *under* the one that contains it and the stack
 * would answer with the outer machine. `closest` reads the tree, which is the
 * thing that is actually nested.
 *
 * `contains` is the shadow-aware half: `closest` stops at a shadow boundary, so a
 * focus inside an open shadow root answers `null` and falls back to containment,
 * which is the right answer — a shadow tree with its own `tabs` in it is its own
 * component either way.
 */
export function ownsFocus(scope: Scope): boolean {
  const root = getRootEl(scope);
  const active = scope.getActiveElement();
  if (root === null || active === null) return false;
  const owner = active.closest(ROOT_SELECTOR);
  return owner === null ? contains(root, active) : owner === root;
}

/** Whether the focus is on one of the triggers rather than out in a panel. */
export function isFocusInList(scope: Scope): boolean {
  return contains(getListEl(scope), scope.getActiveElement());
}

/**
 * A tab list has no lifecycle — one state, everything on the root `on:`, the same
 * shape as `toggle-group`. What it does have is three things that one did not.
 *
 * **The indicator is measured, never derived from an index.** Tabs are as wide as
 * their labels, so an index is not a position and arithmetic on one would put the
 * pill next to the tab it points at. The geometry lives in
 * `utils/indicator-rect`, is pure, and is expressed logically so RTL needs no
 * second rule anywhere.
 *
 * **`syncTriggers` re-settles the value.** APG says a tab list always has exactly
 * one selected tab; a consumer who passes no `defaultValue`, or whose selected tab
 * is removed, must still get that invariant. Re-settling costs nothing here
 * because the trigger list is read from the DOM anyway.
 *
 * **LB/RB reach in from anywhere in the root**, panel included (CDC §4.4), and the
 * scope is deliberately neither `trapped` nor `base` — the popover's reasoning
 * exactly: a trapping scope answers `consumed` to everything it declines, and the
 * spatial engine is at the bottom of the stack, so a trapping tab list would make
 * its own panel unreachable to a d-pad.
 */

import { observeChildren, observeResize } from "../../dom/observers";
import { resolveDir } from "../../dom/text-dir";
import { resolveEnvironment } from "../../environment/environment";
import { getInitialIndex, getNextIndex, getRemovalIndex } from "../../focus/roving-focus";
import { trackInlineScrollbar } from "../../interaction/inline-scrollbar";
import { scrollIntoInlineView, trackInlineScrollEdges } from "../../interaction/scroll-edges";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams } from "../../machine/types";
import { focusElement, getInputModality, getTabbables, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getIndicatorMetrics } from "../../utils/indicator-rect";
import {
  getContentEl,
  getListEl,
  getRootEl,
  getScrollbarEl,
  getThumbEl,
  getTriggerEl,
  getTriggerEls,
  getTriggerValues,
  isFocusInList,
  ownsFocus,
} from "./tabs.dom";
import type { TabsSchema } from "./tabs.types";

type Params = MachineParams<TabsSchema>;

function disabledAt(triggers: readonly HTMLElement[]): (index: number) => boolean {
  return (index: number): boolean => triggers[index]?.hasAttribute("disabled") === true;
}

/**
 * Focus, then the list's own scroll brings the tab into view: a tab half under the
 * fade or fully out of the visible window is where the arrows and the shoulder
 * buttons land. A vertical list has no inline overflow and is left alone.
 */
function focusElementInView(
  { prop, scope }: Pick<Params, "prop" | "scope">,
  target: HTMLElement,
): void {
  focusElement(target);
  if (prop("orientation") !== "vertical") scrollIntoInlineView(getListEl(scope), target);
}

/**
 * The one place `value` is written. `animated` is the whole reason it exists: a
 * pill springs into place when a person chose a tab, and snaps when a layout did
 * — the first settle of `syncTriggers` is a layout, not a choice.
 */
function commitValue(params: Params, value: string | null, animated = true): void {
  const { context, refs } = params;
  if (context.get("value") === value) return;
  context.set("indicatorAnimated", animated);
  if (value !== null) refs.get("visited").add(value);
  context.set("value", value);
}

export const machine: Machine<TabsSchema> = createMachine<TabsSchema>({
  props({ props }) {
    return {
      orientation: "horizontal",
      activationMode: "automatic",
      loopFocus: true,
      disabled: false,
      closable: false,
      lazyMount: false,
      keepMounted: false,
      scrollActiveIntoView: true,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      value: bindable<string | null>(() => ({
        defaultValue: prop("defaultValue") ?? null,
        value: prop("value"),
        onChange: (value) => prop("onValueChange")?.({ value }),
        debugLabel: "tabs value",
      })),
      focusedValue: bindable<string | null>(() => ({
        defaultValue: null,
        onChange: (value) => prop("onFocusChange")?.({ value }),
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      activeIndex: bindable<number>(() => ({ defaultValue: -1 })),
      tabbableValue: bindable<string | null>(() => ({ defaultValue: null })),
      itemCount: bindable<number>(() => ({ defaultValue: 0 })),
      indicatorOffset: bindable<number | null>(() => ({ defaultValue: null })),
      indicatorSize: bindable<number | null>(() => ({ defaultValue: null })),
      indicatorAnimated: bindable<boolean>(() => ({ defaultValue: false })),
      contentTabbable: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  refs() {
    return { visited: new Set<string>(), reveal: null };
  },

  computed: {
    selected: ({ context }) => context.get("value"),
    interactive: ({ prop }) => !prop("disabled"),
  },

  initialState() {
    return "idle";
  },

  effects: [
    "trackModality",
    "trackTriggers",
    "trackIndicator",
    "trackScrollEdges",
    "trackScrollbar",
    "captureIntents",
  ],

  watch({ context, scope, prop, track, action }) {
    // The trigger list is a dependency like any other, so an adapter that
    // re-renders keeps the indicator in step synchronously and the observer below
    // is left to cover the mutations no render caused.
    //
    // The separator is spelled out rather than typed: a raw NUL byte makes ripgrep
    // classify the file as binary, which hid two machines from every grep in the
    // repo once already. It stays U+0000 because that is the one character an
    // attribute value cannot carry, so two different tab lists can never key the
    // same.
    track(
      () => [
        context.get("value"),
        getTriggerValues(scope).join("\u0000"),
        prop("orientation"),
        prop("dir"),
      ],
      () =>
        action(["syncTriggers", "syncIndicator", "syncContentTabbable", "scrollActiveIntoView"]),
    );
  },

  on: {
    "TRIGGER.CLICK": { guard: "isInteractive", actions: ["selectValue"] },
    // Two branches rather than a conditional second action: a transition takes one
    // guard, and `isAutomatic` folds the interactivity test in for that reason.
    "TRIGGER.FOCUS": [
      { guard: "isAutomatic", actions: ["setFocusedValue", "selectValue"] },
      { actions: ["setFocusedValue"] },
    ],
    "TRIGGER.BLUR": { actions: ["clearFocus"] },
    "TRIGGER.NAVIGATE": { guard: "isInteractive", actions: ["navigate"] },
    // Enter and Space. On a real `<button>` the browser also produces a click, so
    // this path is what keeps a substituted element correct; the second commit is
    // a no-op because the value is already the one being asked for.
    "TRIGGER.ACTIVATE": { guard: "isInteractive", actions: ["selectValue"] },
    "TRIGGER.CLOSE": { guard: "isClosable", actions: ["closeTab"] },
    "LIST.NEXT": { guard: "isInteractive", actions: ["stepValue"] },
    "LIST.PREV": { guard: "isInteractive", actions: ["stepValue"] },
    "VALUE.SET": { actions: ["setValue"] },
    "TRIGGERS.SYNC": {
      actions: ["syncTriggers", "syncIndicator", "syncContentTabbable", "revealClosedSuccessor"],
    },
    "INDICATOR.MEASURE": { actions: ["syncIndicator"] },
  },

  states: {
    idle: {},
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled"),
      isAutomatic: ({ prop }) => !prop("disabled") && prop("activationMode") === "automatic",
      isClosable: ({ prop }) => !prop("disabled") && prop("closable"),
    },

    actions: {
      selectValue(params) {
        const { event } = params;
        if (
          event.type === "TRIGGER.CLICK" ||
          event.type === "TRIGGER.ACTIVATE" ||
          event.type === "TRIGGER.FOCUS"
        ) {
          commitValue(params, event.value);
        }
      },

      setValue(params) {
        if (params.event.type === "VALUE.SET") commitValue(params, params.event.value);
      },

      setFocusedValue({ context, event, scope }) {
        if (event.type !== "TRIGGER.FOCUS") return;
        context.set("focusedValue", event.value);
        // Read here and held: an arrow key moving between tabs is a new focus, so
        // the source follows a keyboard user across the list, while a mouse merely
        // crossing the page never touches it.
        context.set("focusSource", getInputModality(scope.getDoc()));
      },

      clearFocus({ context }) {
        context.set("focusedValue", null);
        context.set("focusSource", null);
      },

      /**
       * Moves the focus and nothing else. In `automatic` mode the selection
       * follows, but it arrives through `TRIGGER.FOCUS` — one path, whether the
       * focus was moved by an arrow, a d-pad or a click.
       */
      navigate(params) {
        const { prop, scope, event } = params;
        if (event.type !== "TRIGGER.NAVIGATE") return;
        const triggers = getTriggerEls(scope);
        const current = triggers.findIndex((trigger) => trigger.dataset.value === event.value);
        const next = getNextIndex(current, event.action, {
          count: triggers.length,
          loop: prop("loopFocus"),
          isDisabled: disabledAt(triggers),
        });
        const target = triggers[next];
        if (target === undefined || next === current) return;
        focusElementInView(params, target);
      },

      /**
       * LB/RB, and `api.selectNext()`. The selection steps whatever has the focus;
       * the focus only follows when it was in the list already — a shoulder button
       * pressed while the user is reading a panel must not tear them out of it.
       */
      stepValue(params) {
        const { context, prop, scope, event } = params;
        if (event.type !== "LIST.NEXT" && event.type !== "LIST.PREV") return;
        const triggers = getTriggerEls(scope);
        const values = triggers.map((trigger) => trigger.dataset.value ?? "");
        const current = values.indexOf(context.get("value") ?? "");
        const next = getNextIndex(current, event.type === "LIST.NEXT" ? "next" : "prev", {
          count: triggers.length,
          loop: prop("loopFocus"),
          isDisabled: disabledAt(triggers),
        });
        const target = triggers[next];
        if (target === undefined || next === current) return;

        const followFocus = isFocusInList(scope);
        commitValue(params, target.dataset.value ?? null);
        if (followFocus) focusElementInView(params, target);
      },

      /**
       * The consumer owns the removal — `onClose` is the whole request. What the
       * machine owns is where the focus and the selection land afterwards: the next
       * tab, the previous one when there is no next (APG), and `null` when the tab
       * closed was the only one there was.
       */
      closeTab(params) {
        const { context, prop, scope, event } = params;
        if (event.type !== "TRIGGER.CLOSE") return;
        const triggers = getTriggerEls(scope);
        const index = triggers.findIndex((trigger) => trigger.dataset.value === event.value);
        if (index === -1) return;

        const wasSelected = context.get("value") === event.value;
        // Whether the focus is on the tab being closed — its trigger or its close
        // button, and both carry the value. Read before `onClose`, because the
        // consumer removes the tab from inside it. A middle click on a background
        // tab must not pull the focus into the bar, and in `automatic` mode that
        // focus would drag the selection along with it.
        const active = scope.getActiveElement();
        const hadFocus =
          active !== null && isFocusInList(scope) && active.dataset.value === event.value;
        prop("onClose")?.({ value: event.value });

        const target =
          triggers[
            getRemovalIndex(index, { count: triggers.length, isDisabled: disabledAt(triggers) })
          ];
        if (target === undefined) {
          if (wasSelected) commitValue(params, null);
          return;
        }
        if (hadFocus) {
          focusElement(target);
          params.refs.set("reveal", { target, count: triggers.length });
        }
        if (wasSelected) commitValue(params, target.dataset.value ?? null);
      },

      /**
       * The successor of a closed tab is revealed once the list has actually lost a
       * tab, which the observer reports whenever the consumer's removal commits:
       * inside its handler, after a timer or in a transition. Before that the tabs
       * after the closed one are still where they were, and a reveal would place
       * the focus for a layout that is about to change. Only if the successor still
       * has the focus: a person who moved on does not get scrolled back.
       */
      revealClosedSuccessor({ prop, refs, scope }) {
        const pending = refs.get("reveal");
        if (pending === null || getTriggerEls(scope).length >= pending.count) return;
        refs.set("reveal", null);
        if (prop("orientation") === "vertical" || scope.getActiveElement() !== pending.target) {
          return;
        }
        scrollIntoInlineView(getListEl(scope), pending.target);
      },

      /**
       * The DOM order is the tab order, and the selected tab is the single tab
       * stop, so the index has to be a fact about the DOM rather than about the
       * value. Re-settling `value` here is what gives a consumer the APG invariant
       * — a tab list always has one selected tab — without having to pass a
       * `defaultValue`, and what rescues a value left dangling by a removed tab.
       */
      syncTriggers(params) {
        const { context, refs, scope } = params;
        const value = context.get("value");
        // Every value the list has actually held, recorded here and not only in
        // `commitValue`: a controlled consumer moves the value from outside, and
        // `lazyMount` promises a panel that has been shown once stays built.
        if (value !== null) refs.get("visited").add(value);

        // No root yet — a server render, or the first client render before the
        // mount effect. "I cannot see the tabs" is not "there are no tabs", and
        // settling on that would report a change to a controlled consumer before
        // the component exists at all.
        if (getRootEl(scope) === null) return;

        const triggers = getTriggerEls(scope);
        const values = triggers.map((trigger) => trigger.dataset.value ?? "");
        const isDisabled = disabledAt(triggers);
        context.set("itemCount", values.length);

        let index = value === null ? -1 : values.indexOf(value);
        // Disabled counts as unselectable, not merely as un-clickable: the tab stop
        // rides on the selection, and parked on a disabled button the composite's
        // only `tabindex="0"` is skipped and the whole list leaves the tab order.
        if (index === -1 || isDisabled(index)) {
          const fallback = getInitialIndex({ count: values.length, isDisabled });
          // Nothing selectable at all. An empty list drops the value; a list that
          // is merely disabled keeps it — clearing there would erase the
          // consumer's state and report a change nobody made, and a disabled list
          // has no tab stop to rescue anyway.
          if (fallback !== -1 || values.length === 0) {
            index = fallback;
            commitValue(params, values[fallback] ?? null, false);
          }
        }
        context.set("activeIndex", index);
        // The single tab stop, published as a value rather than derived from the
        // selection in `connect`. A controlled consumer may hold `value` at `null`
        // — the types call that a value, not an absence — and `syncTriggers` is
        // right not to re-settle it for them; but a stop that rode on the selection
        // then left *every* trigger at `tabindex="-1"`, and the whole list fell out
        // of the tab order. It falls back to the tab this settle would have chosen.
        context.set(
          "tabbableValue",
          index !== -1 && !isDisabled(index) ? (values[index] ?? null) : null,
        );
      },

      syncIndicator({ context, prop, scope, event }) {
        if (event.type === "INDICATOR.MEASURE") context.set("indicatorAnimated", event.animated);

        const list = getListEl(scope);
        const value = context.get("value");
        const trigger = value === null ? null : getTriggerEl(scope, value);
        if (list === null || trigger === null) {
          context.set("indicatorOffset", null);
          context.set("indicatorSize", null);
          return;
        }

        const metrics = getIndicatorMetrics(
          list.getBoundingClientRect(),
          trigger.getBoundingClientRect(),
          list,
          // From the list, which is where the measured geometry lives: with no
          // `dir` prop the sign of the offset follows whatever the page resolved
          // around the tablist.
          { orientation: prop("orientation"), dir: resolveDir(prop("dir"), list) },
        );
        context.set("indicatorOffset", metrics.offset);
        context.set("indicatorSize", metrics.size);
      },

      /**
       * Measured, never assumed. A panel of plain text is unreachable by keyboard
       * unless it takes a tab stop of its own; a panel holding a link or a field
       * that took one would put an empty stop in front of them.
       */
      syncContentTabbable({ context, scope }) {
        const value = context.get("value");
        const content = value === null ? null : getContentEl(scope, value);
        context.set("contentTabbable", content !== null && getTabbables(content).length === 0);
      },

      scrollActiveIntoView({ context, prop, scope }) {
        if (!prop("scrollActiveIntoView")) return;
        const list = getListEl(scope);
        const value = context.get("value");
        const trigger = value === null ? null : getTriggerEl(scope, value);
        if (list === null || trigger === null) return;

        const overflows =
          prop("orientation") === "vertical"
            ? list.scrollHeight > list.clientHeight
            : list.scrollWidth > list.clientWidth;
        if (!overflows) return;

        trigger.scrollIntoView({
          block: "nearest",
          inline: "nearest",
          // The same resolution order as the styles layer: attributes first, media
          // query second, so an app pinned to `data-motion="reduced"` is obeyed.
          behavior: resolveEnvironment(list).reducedMotion ? "auto" : "smooth",
        });
      },
    },

    effects: {
      // No listener: the source is read once, when the focus lands. Holding the
      // handle is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackTriggers({ scope, send }) {
        send({ type: "TRIGGERS.SYNC" });
        // Tabs appear and disappear with the app's own state; the indicator has to
        // survive that without the consumer telling anyone.
        return observeChildren(getListEl(scope), () => send({ type: "TRIGGERS.SYNC" }));
      },

      /**
       * `animated: false` throughout: a pill must not play a spring because the
       * window moved or a font finished loading.
       */
      trackIndicator({ scope, send }) {
        let disposed = false;
        const measure = (): void => {
          if (!disposed) send({ type: "INDICATOR.MEASURE", animated: false });
        };

        const list = getListEl(scope);
        const stopList = observeResize(list, measure);

        /**
         * Every trigger, never "the selected one". `machine.effects` are installed
         * once by `start()` and are never re-armed on a context change, so an
         * observer aimed at the selection would stay aimed at whichever tab was
         * selected at mount — and at nothing at all for a list that starts without
         * one, which is every list with no `defaultValue`. The list's own box does
         * not answer for a child that grew inside it once the list is a fixed-size
         * scroller, and that is exactly the `tab-bar` presentation this sheet is
         * being built for.
         */
        const observeTriggers = (): VoidFunction => {
          const stops = getTriggerEls(scope).map((trigger) => observeResize(trigger, measure));
          return (): void => {
            for (const stop of stops) stop();
          };
        };

        let stopTriggers = observeTriggers();
        // Re-armed rather than re-measured: the measurement on a child mutation is
        // already `trackTriggers`' job, and doing it twice would spring the pill
        // for one layout change.
        const stopChildren = observeChildren(list, () => {
          stopTriggers();
          stopTriggers = observeTriggers();
        });

        // A one-shot, and the flag is why the disposer sets one at all: the promise
        // outlives the effect, and a measurement after teardown is a `send` into a
        // stopped service.
        const { fonts } = scope.getDoc();
        void fonts?.ready.then(measure);

        return () => {
          disposed = true;
          stopChildren();
          stopTriggers();
          stopList();
        };
      },

      /**
       * A list wider than the room it is given scrolls along its inline axis, and
       * a hidden scrollbar says nothing about it: the sheet fades the edge this
       * attribute names. Written on the list, which is the scroller.
       */
      trackScrollEdges({ prop, scope, send }) {
        return trackInlineScrollEdges(getListEl(scope), {
          active: () => prop("orientation") !== "vertical" && !prop("disabled"),
          attributes: ["data-disabled"],
          onToggle: () => send({ type: "INDICATOR.MEASURE", animated: false }),
        });
      },

      /**
       * The drawn bar of that scroller, a sibling a composed layer or a parts tree
       * places after the list; without one there is nothing to bind.
       */
      trackScrollbar({ scope }) {
        return trackInlineScrollbar(getListEl(scope), getScrollbarEl(scope), getThumbEl(scope));
      },

      /**
       * Neither `trapped` nor `base`. `tabNext`/`tabPrev` escape a trap by design
       * (`TRAP_ESCAPES`), so a `tabs` inside a dialog stays drivable from a pad —
       * which is the point. `back` is deliberately not claimed: a tab list is not a
       * layer, and one that swallowed B would make a dialog containing tabs
       * impossible to leave.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        if (host === null || host === undefined) return;
        return host.pushScope(
          (event) => {
            if (event.intent !== "tabNext" && event.intent !== "tabPrev") return false;
            // A nested `tabs` wins, whatever order the two mounted in — the tree
            // decides, not the scope stack. See `ownsFocus`.
            if (prop("disabled") || !ownsFocus(scope)) return false;
            send({ type: event.intent === "tabNext" ? "LIST.NEXT" : "LIST.PREV" });
            return true;
          },
          { within: () => getRootEl(scope) },
        );
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Direction, InputModality, Orientation } from "../../types";

/**
 * `automatic` is the default, which diverges from how `components.md` §4 reads.
 * It is the APG recommendation whenever a panel is cheap, and it is what a tab
 * bar feels like under a d-pad. `manual` is the documented answer for an
 * expensive panel — pair it with `lazyMount` — not a fork of the machine.
 */
export type TabsActivationMode = "automatic" | "manual";

export interface TabsValueChangeDetails {
  readonly value: string | null;
}

export interface TabsFocusChangeDetails {
  readonly value: string | null;
}

export interface TabsCloseDetails {
  readonly value: string;
}

export interface TabsTriggerProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
  /**
   * The tab's own text, repeated so the styles can reserve the width the label
   * takes at the selected weight. Without it the tab widens when it is selected,
   * and the indicator — which is *measured* — chases a width it just caused.
   * Optional; the weight change is gated on the attribute being there.
   */
  readonly label?: string | undefined;
}

export interface TabsContentProps {
  readonly value: string;
}

export interface TabsCloseTriggerProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
}

export interface TabsMachineProps {
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly orientation?: Orientation | undefined;
  /** Controlled. `null` is a value — it means no tab is selected. */
  readonly value?: string | null | undefined;
  readonly defaultValue?: string | null | undefined;
  readonly activationMode?: TabsActivationMode | undefined;
  readonly loopFocus?: boolean | undefined;
  /** The whole tab list. Individual tabs disable themselves on the trigger. */
  readonly disabled?: boolean | undefined;
  /** Opens the close trigger, the `Delete` key and the middle click. */
  readonly closable?: boolean | undefined;
  /** A panel does not exist until its tab has been activated once. */
  readonly lazyMount?: boolean | undefined;
  /** A panel stays rendered, `hidden`, after it is deactivated. */
  readonly keepMounted?: boolean | undefined;
  /** Brings the selected tab back into view when the list overflows. */
  readonly scrollActiveIntoView?: boolean | undefined;
  /** Ids of the text describing this control — a `field` supplies them. */
  readonly describedBy?: string | undefined;
  /** Where LB/RB arrive from. `null` when the app runs no input system. */
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onValueChange?: ((details: TabsValueChangeDetails) => void) | undefined;
  readonly onFocusChange?: ((details: TabsFocusChangeDetails) => void) | undefined;
  /** The consumer removes the tab; the machine only says which one and moves on. */
  readonly onClose?: ((details: TabsCloseDetails) => void) | undefined;
}

export interface ResolvedTabsMachineProps extends TabsMachineProps {
  readonly orientation: Orientation;
  readonly activationMode: TabsActivationMode;
  readonly loopFocus: boolean;
  readonly disabled: boolean;
  readonly closable: boolean;
  readonly lazyMount: boolean;
  readonly keepMounted: boolean;
  readonly scrollActiveIntoView: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface TabsSchema extends MachineSchema {
  state: "idle";
  props: ResolvedTabsMachineProps;
  context: {
    value: string | null;
    /** The tab that actually holds DOM focus, if any. */
    focusedValue: string | null;
    /** Read once, when the focus lands, and held until it leaves. */
    focusSource: InputModality | null;
    /** Where the selected tab sits. `-1` when nothing is selected. */
    activeIndex: number;
    /**
     * The tab carrying the list's single tab stop. It is the selected tab whenever
     * there is one, and the first enabled tab when there is not — a controlled
     * consumer is allowed to hold `value` at `null`, and a tab list that answered
     * that by leaving the tab order entirely would be unreachable by keyboard.
     * `null` only when nothing in the list can be selected at all.
     */
    tabbableValue: string | null;
    itemCount: number;
    /** Measured, in CSS pixels, from the list's padding-box start. */
    indicatorOffset: number | null;
    indicatorSize: number | null;
    /** False for a first paint, a resize or a font swap — never a spring then. */
    indicatorAnimated: boolean;
    /** The selected panel has no tabbable descendant, so it needs a tab stop. */
    contentTabbable: boolean;
  };
  refs: {
    /**
     * A ref rather than context: a first activation is always *caused* by a change
     * of `value`, which has already asked for a render. Nothing here is ever the
     * reason to paint.
     */
    visited: Set<string>;
    /**
     * The tab a closed one hands the focus to, with the number of tabs there were
     * when it was closed: revealed once the list has fewer.
     */
    reveal: { target: HTMLElement; count: number } | null;
  };
  computed: {
    selected: string | null;
    interactive: boolean;
  };
  event:
    | { type: "TRIGGER.CLICK"; value: string }
    | { type: "TRIGGER.FOCUS"; value: string }
    | { type: "TRIGGER.BLUR" }
    | { type: "TRIGGER.NAVIGATE"; action: RovingAction; value: string }
    | { type: "TRIGGER.ACTIVATE"; value: string }
    | { type: "TRIGGER.CLOSE"; value: string }
    | { type: "LIST.NEXT" }
    | { type: "LIST.PREV" }
    | { type: "VALUE.SET"; value: string | null }
    | { type: "TRIGGERS.SYNC" }
    | { type: "INDICATOR.MEASURE"; animated: boolean };
  action:
    | "selectValue"
    | "setValue"
    | "setFocusedValue"
    | "clearFocus"
    | "navigate"
    | "stepValue"
    | "closeTab"
    | "syncTriggers"
    | "syncIndicator"
    | "syncContentTabbable"
    | "scrollActiveIntoView"
    | "revealClosedSuccessor";
  guard: "isInteractive" | "isAutomatic" | "isClosable";
  effect:
    | "trackModality"
    | "trackTriggers"
    | "trackIndicator"
    | "trackScrollEdges"
    | "trackScrollbar"
    | "captureIntents";
}

export interface TabsApi<T extends PropTypes = PropTypes> {
  readonly value: string | null;
  readonly focusedValue: string | null;
  readonly disabled: boolean;
  isSelected(value: string): boolean;
  /** Whether the panel should be rendered at all — the `lazyMount` gate. */
  isMounted(value: string): boolean;
  setValue(value: string | null): void;
  /** The LB/RB step, exposed so an app can drive it from its own chrome. */
  selectNext(): void;
  selectPrev(): void;
  getRootProps(): T["element"];
  getListProps(): T["element"];
  getTriggerProps(props: TabsTriggerProps): T["button"];
  getIndicatorProps(): T["element"];
  getScrollbarProps(): T["element"];
  getThumbProps(): T["element"];
  getContentProps(props: TabsContentProps): T["element"];
  getCloseTriggerProps(props: TabsCloseTriggerProps): T["button"];
}

/**
 * `<Tabs items={…}/>` — and the first composed layer that places every entry
 * **twice, in two different parents**.
 *
 * Every composed component before this one had a single loop: `select` and
 * `radio-group` place one item per option, `pagination` one cell per page. A tab
 * list has a trigger inside `TabsList` and a panel outside it, both keyed by the
 * same `value`, and the two collections are not interleaved in the markup — the
 * whole list comes first, then the whole set of panels (`ssr.test.tsx:498-510`).
 * So this file loops the same array twice rather than building one tree, and the
 * shape is the anatomy's rather than a choice: `getTriggerEls` reads the list, and
 * a panel written inside it would be a `role="tabpanel"` owned by a
 * `role="tablist"`.
 *
 * **`flatMap` rather than a keyed fragment**, and it is the close button that
 * decides it. A close trigger is a *sibling* of the tab it closes and never its
 * child (`tabs.tsx:164-169`) — a `<button>` may hold no interactive content, and a
 * nested one would hand its click to the tab on the way out, selecting the tab the
 * user just asked to be rid of. A `<Fragment key>` around the pair would render no
 * node and pass the parity comparison, but it would also write the pair as a unit
 * in the source, which is the one thing the anatomy says they are not.
 *
 * **`label` is the text and the reservation, and here that matters more than it
 * does on a segmented control.** `TabsTriggerProps.label` is written to
 * `data-label` so the styles can reserve the width the tab takes at its *selected*
 * weight (`tabs.types.ts:30-36`). Skip it and the tab widens when it is selected —
 * and the indicator, which is measured off the DOM rather than derived from an
 * index (`--sui-indicator-offset`/`-size`), then chases a width it caused itself.
 * So `label` is required on an entry and spent twice, exactly as
 * `toggle-group/composed.tsx` spends its own.
 *
 * **The close trigger asks for no name, and that is the finding worth writing
 * down.** `dialog:close-trigger` and `input:visibility-trigger` have no default
 * accessible name, so a composed layer has to require one or not render the part.
 * This one is not in that family: `getCloseTriggerProps` writes `aria-hidden` and
 * `tabIndex: -1` itself (`tabs.connect.ts:288-291`) because `role="tablist"` may
 * own nothing but `role="tab"`, and the keyboard route to closing is `Delete` on
 * the tab, per APG. A `closeLabel` per entry would therefore be a name nothing
 * ever announces — a slot that reads like a11y and buys none. The part is placed
 * under `closable` and left nameless.
 */

import type {
  TabsCloseTriggerProps as CoreTabsCloseTriggerProps,
  TabsContentProps as CoreTabsContentProps,
  TabsTriggerProps as CoreTabsTriggerProps,
} from "@standarui/core/tabs";
import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  TabsCloseTrigger,
  TabsContent,
  TabsIndicator,
  TabsList,
  TabsRoot,
  TabsScrollbar,
  TabsThumb,
  TabsTrigger,
  type UseTabsProps,
} from "./tabs";

/**
 * One tab and its panel. `value` is the identity the machine reads everything else
 * back off — position, neighbours, the tab stop — and `label` is narrowed from
 * optional to required because this is the only place both of its meanings, the
 * drawn text and the reserved width, come from.
 */
export interface TabsItem {
  readonly value: string;
  readonly label: string;
  /** The panel's content. A tab with an empty panel still has one to point at. */
  readonly content?: ReactNode;
  /** This tab alone. The whole list is disabled by `disabled` on the root. */
  readonly disabled?: boolean | undefined;
}

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 */
export interface TabsParts {
  readonly list?: PartProps<"div"> | undefined;
  readonly indicator?: PartProps<"span"> | undefined;
  readonly scrollbar?: PartProps<"div"> | undefined;
  readonly thumb?: PartProps<"div"> | undefined;
  /**
   * Applied to EVERY tab, hence no `value`, `label` or `disabled` — the entry's
   * own fields, already excluded through `Own` — and no `id` **or IDREF**: one id
   * repeated down a list is a broken reference per tab, and one `aria-labelledby`
   * repeated gives every tab the same name, which no dangling-IDREF check can see
   * because the id it points at does resolve. `aria-controls` goes with them for a
   * sharper reason than the others: the machine writes it only where the panel it
   * names is provably in the same markup (`ssr.test.tsx:494-496`), and a fixed one
   * here would undo exactly that guarantee. `ref` goes because a single ref held
   * by N tabs ends up holding the last one.
   */
  readonly trigger?:
    | Omit<
        PartProps<"button", CoreTabsTriggerProps>,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  /**
   * Applied to EVERY close button, and excluded for the same reasons. The `Own`
   * parameter is not decoration here: `<button>` has a DOM attribute called
   * `value`, typed `string | number | readonly string[]`, and without it the hatch
   * would widen the part's own `value: string` — a spread applied last wins on the
   * type as well as at runtime.
   */
  readonly closeTrigger?:
    | Omit<
        PartProps<"button", CoreTabsCloseTriggerProps>,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  /** Applied to EVERY panel, and excluded for the same reasons. */
  readonly content?:
    | Omit<
        PartProps<"div", CoreTabsContentProps>,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
}

export interface TabsComposedProps
  extends UseTabsProps,
    Omit<PartProps<"div", UseTabsProps>, "children"> {
  readonly items: readonly TabsItem[];
  readonly parts?: TabsParts | undefined;
}

export function Tabs(props: TabsComposedProps): ReactNode {
  const { items, parts, ...root } = props;

  return (
    <TabsRoot {...root}>
      <TabsList {...parts?.list}>
        {/* Written first so it paints under the tabs it slides beneath. */}
        <TabsIndicator {...parts?.indicator} />
        {items.flatMap((item) => [
          <TabsTrigger
            key={item.value}
            value={item.value}
            label={item.label}
            disabled={item.disabled}
            {...parts?.trigger}
          >
            {item.label}
          </TabsTrigger>,
          root.closable === true ? (
            <TabsCloseTrigger
              key={`${item.value}:close`}
              value={item.value}
              disabled={item.disabled}
              {...parts?.closeTrigger}
            />
          ) : null,
        ])}
      </TabsList>
      <TabsScrollbar {...parts?.scrollbar}>
        <TabsThumb {...parts?.thumb} />
      </TabsScrollbar>
      {items.map((item) => (
        <TabsContent key={item.value} value={item.value} {...parts?.content}>
          {item.content}
        </TabsContent>
      ))}
    </TabsRoot>
  );
}

/**
 * Tabs in React: one machine in the root, and one panel per value that has to be
 * allowed to finish leaving.
 *
 * Two things are wired here that a consumer should never have to wire by hand:
 * the intent scope LB/RB arrive on, taken from the nearest `<NavProvider>`,
 * and the field a tab list may sit in, which is where `describedBy` comes from.
 *
 * **The presence lives on the panel, not on the root.** A dialog has one surface
 * and keeps its presence in the root context; a tab list has one panel per value,
 * and the panel that is leaving is never the panel that is arriving — a single
 * presence could only measure the animations of whichever node it happened to
 * hold. One per `<TabsContent>` is also what keeps a panel that has never been
 * activated from paying for one at all (`lazyMount` unmounts it outright).
 *
 * Nothing here decides *what* is selected, mounted or focused: `isSelected`,
 * `isMounted` and the whole roving order come off the machine, so the React
 * adapter and the vanilla one cannot drift on the questions that matter.
 */

import type { Service } from "@standarui/core";
import * as tabs from "@standarui/core/tabs";
import { type ReactNode, type Ref, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { inheritFromField, useFieldContext } from "../../field-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { usePresence } from "../../presence";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type TabsApi = tabs.TabsApi<ReactPropTypes>;

export interface UseTabsProps extends tabs.TabsMachineProps, MachineRuntimeProps {}

interface TabsContextValue {
  readonly api: TabsApi;
  /**
   * Mirrored out of the machine props rather than read back off the api: it is
   * the panels that act on it, and `connect` already spends it on the `hidden`
   * attribute. Only the mount decision is left, and that one is React's.
   */
  readonly keepMounted: boolean;
}

const TabsContext = createPartContext<TabsContextValue>("Tabs");

function useTabsService(props: UseTabsProps): Service<tabs.TabsSchema> {
  const host = useIntentScopeHost();

  return useMachine(tabs.machine, {
    ...props,
    // `??` would override an explicit `null`, and `null` is how a consumer says
    // "this tab list answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
  });
}

export function useTabs(props: UseTabsProps): TabsApi {
  return tabs.connect(useTabsService(props), normalizeProps);
}

/** The api of the tab list a subtree sits in — a consumer's own chrome reads it. */
export function useTabsContext(): TabsApi {
  return TabsContext.usePart("TabsContext").api;
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "orientation",
  "value",
  "defaultValue",
  "activationMode",
  "loopFocus",
  "disabled",
  "closable",
  "lazyMount",
  "keepMounted",
  "scrollActiveIntoView",
  "describedBy",
  "intents",
  "onValueChange",
  "onFocusChange",
  "onClose",
] as const;

export interface TabsRootProps extends UseTabsProps, PartProps<"div", UseTabsProps> {}

export function TabsRoot(props: TabsRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const field = useFieldContext();
  const api = useTabs(inheritFromField(machineProps, field));

  const context: TabsContextValue = { api, keepMounted: machineProps.keepMounted === true };

  return (
    <TabsContext.Provider value={context}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </TabsContext.Provider>
  );
}

export const TabsList: (props: PartProps<"div">) => ReactNode = createPart(TabsContext, {
  name: "TabsList",
  element: "div",
  props: (context) => context.api.getListProps(),
});

/**
 * Decoration, and `aria-hidden` says so. It is placed by the two custom
 * properties the machine measured onto `list`, so it renders wherever the author
 * put it inside that list and nothing here has to know about geometry.
 */
export const TabsIndicator: (props: PartProps<"span">) => ReactNode = createPart(TabsContext, {
  name: "TabsIndicator",
  element: "span",
  props: (context) => context.api.getIndicatorProps(),
});

/**
 * The drawn bar of a list that scrolls along its line, a **sibling** of the list
 * and never inside it: a child of a scroller scrolls with it and is clipped and
 * faded by it. Opt-in for a parts tree, and decoration, hence `aria-hidden`.
 */
export const TabsScrollbar: (props: PartProps<"div">) => ReactNode = createPart(TabsContext, {
  name: "TabsScrollbar",
  element: "div",
  props: (context) => context.api.getScrollbarProps(),
});

export const TabsThumb: (props: PartProps<"div">) => ReactNode = createPart(TabsContext, {
  name: "TabsThumb",
  element: "div",
  props: (context) => context.api.getThumbProps(),
});

export interface TabsTriggerProps
  extends tabs.TabsTriggerProps,
    PartProps<"button", tabs.TabsTriggerProps> {}

/**
 * A tab is identified by its value and nothing else: its position, its
 * neighbours and whether it is the tab stop are all read back off the DOM by the
 * machine, which is what stops a conditionally rendered tab going out of sync
 * with a registry nobody remembered to update.
 */
export function TabsTrigger(props: TabsTriggerProps): ReactNode {
  const [triggerProps, rest] = splitProps(props, ["value", "disabled", "label"]);
  const { render, asChild, children, ...elementProps } = rest;
  const context = TabsContext.usePart("TabsTrigger");

  return useRender({
    render,
    asChild,
    element: "button",
    props: context.api.getTriggerProps(triggerProps),
    elementProps,
    children,
  });
}

export interface TabsCloseTriggerProps
  extends tabs.TabsCloseTriggerProps,
    PartProps<"button", tabs.TabsCloseTriggerProps> {}

/**
 * A **sibling** of the tab it closes, never a child of it: a `<button>` may hold
 * no interactive content, and a close button nested in one would also hand its
 * click to the tab on the way out — selecting the tab the user just asked to be
 * rid of. `getTriggerEls` reads `[data-part~="tabs:trigger"]`, and `close-trigger`
 * is a different token, so a sibling changes nothing about the roving order.
 *
 * It takes no tab stop: the list exposes exactly one, and the keyboard route to
 * closing is `Delete` (APG). Only live under `closable` — the machine declines
 * `TRIGGER.CLOSE` otherwise, so a stray one is inert rather than wrong.
 */
export function TabsCloseTrigger(props: TabsCloseTriggerProps): ReactNode {
  const [closeProps, rest] = splitProps(props, ["value", "disabled"]);
  const { render, asChild, children, ...elementProps } = rest;
  const context = TabsContext.usePart("TabsCloseTrigger");

  return useRender({
    render,
    asChild,
    element: "button",
    props: context.api.getCloseTriggerProps(closeProps),
    elementProps,
    children,
  });
}

export interface TabsContentProps
  extends tabs.TabsContentProps,
    PartProps<"div", tabs.TabsContentProps> {}

export function TabsContent(props: TabsContentProps): ReactNode {
  const [contentProps, rest] = splitProps(props, ["value"]);
  const { render, asChild, children, ref, ...elementProps } = rest;
  const { api, keepMounted } = TabsContext.usePart("TabsContent");
  const { motion } = useEnvironment();

  const selected = api.isSelected(contentProps.value);
  // `keepMounted` skips the wait the way `data-motion="none"` does: the panel is
  // `hidden` the moment it deactivates, `display: none` runs no animation, and a
  // presence left waiting on one would only schedule a render nobody reads.
  // `reduced` is not in that list — it keeps the 150ms fade, and skipping there
  // would lose the crossfade the sheet keeps on purpose (see `dialog.tsx`).
  const presence = usePresence({ present: selected, immediate: motion === "none" || keepMounted });
  // Memoised on identity: a fresh callback every render would make React detach
  // and re-attach the consumer's own ref on every render too.
  const composed: Ref<HTMLElement> = useMemo(
    () => composeRefs(presence.ref, ref),
    [presence.ref, ref],
  );

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: api.getContentProps(contentProps),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  // `isMounted` is the `lazyMount` gate and it comes first: a panel that has
  // never been activated is not in the tree at all, which is also what keeps
  // `aria-controls` from naming an element that does not exist. Past that gate a
  // panel is present while it is selected, while `keepMounted` holds it, and for
  // as long as its exit is still running — the presence only ever extends a
  // mount past the deactivation, never delays one.
  return api.isMounted(contentProps.value) && (keepMounted || selected || presence.present)
    ? element
    : null;
}
